-- =============================================================================
-- File:     sql/02_create_tables.sql
-- Purpose:  Create every table of the West City Bank data model, exactly as
--           designed in westcity-er-model-source.md (sections 1-7).
-- Runs:     Automatically, once, when the Postgres container starts with an
--           empty data volume (after 01_create_databases.sql).
--           It switches database with \connect, so it must run through psql.
--
-- Conventions used in every database:
--   * Surrogate keys use GENERATED BY DEFAULT AS IDENTITY: Postgres numbers
--     new rows automatically, but seed scripts may still insert fixed ids.
--   * Allowed values (statuses, types, ...) are enforced with CHECK
--     constraints, so bad data is rejected at the source.
--   * Foreign keys exist only INSIDE one database. References to another
--     system (customer_id, account_id, onboarding_session_id) are LOGICAL
--     keys with no foreign key, because each system is independent.
--   * All timestamps are timestamptz (a moment in time); the databases use
--     Australia/Sydney to display them and to derive business dates.
--   * Triggers, the Debezium publication and data come in later scripts.
-- =============================================================================


-- #############################################################################
-- 1. core_banking – system of record for customers and accounts (ER section 1)
-- #############################################################################
\connect core_banking

-- Branch: where an account is domiciled. BSB = 6-digit bank-state-branch code.
CREATE TABLE branch (
    branch_id    integer      GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    bsb          char(6)      NOT NULL UNIQUE CHECK (bsb ~ '^[0-9]{6}$'),
    branch_name  varchar(100) NOT NULL,
    state        varchar(3)   NOT NULL CHECK (state IN ('NSW','VIC','QLD','SA','WA','TAS','NT','ACT'))
);

-- Product: the account products the bank sells.
CREATE TABLE product (
    product_code  varchar(20)  PRIMARY KEY,                          -- e.g. EVERYDAY
    product_name  varchar(100) NOT NULL,
    product_type  varchar(20)  NOT NULL CHECK (product_type IN ('TRANSACTION','SAVINGS')),
    monthly_fee   numeric(8,2) NOT NULL DEFAULT 0 CHECK (monthly_fee >= 0),      -- AUD per month
    interest_rate numeric(5,2) NOT NULL DEFAULT 0 CHECK (interest_rate >= 0),    -- % per year, e.g. 4.50
    is_active     boolean      NOT NULL DEFAULT true
);

-- Customer: the customer master record.
CREATE TABLE customer (
    customer_id        bigint       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    first_name         varchar(100) NOT NULL,
    last_name          varchar(100) NOT NULL,
    date_of_birth      date         NOT NULL,
    email              varchar(255) NOT NULL,
    mobile             varchar(16)  NOT NULL CHECK (mobile ~ '^\+[1-9][0-9]{7,14}$'),  -- E.164, e.g. +61412345678
    marketing_consent  boolean      NOT NULL DEFAULT false,
    statement_delivery varchar(5)   NOT NULL DEFAULT 'EMAIL' CHECK (statement_delivery IN ('PAPER','EMAIL')),
    customer_since     date         NOT NULL DEFAULT current_date,
    version            integer      NOT NULL DEFAULT 1 CHECK (version >= 1),  -- aggregate version, +1 on every change
    created_at         timestamptz  NOT NULL DEFAULT now(),
    updated_at         timestamptz  NOT NULL DEFAULT now()
);

-- Customer address: history of addresses (valid_to is NULL for the current one).
CREATE TABLE customer_address (
    address_id   bigint       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    customer_id  bigint       NOT NULL REFERENCES customer (customer_id),
    address_type varchar(11)  NOT NULL CHECK (address_type IN ('RESIDENTIAL','POSTAL')),
    line1        varchar(200) NOT NULL,
    suburb       varchar(100) NOT NULL,
    state        varchar(3)   NOT NULL CHECK (state IN ('NSW','VIC','QLD','SA','WA','TAS','NT','ACT')),
    postcode     char(4)      NOT NULL CHECK (postcode ~ '^[0-9]{4}$'),
    valid_from   date         NOT NULL DEFAULT current_date,
    valid_to     date,                                               -- NULL = current address
    CHECK (valid_to IS NULL OR valid_to >= valid_from)
);
-- At most one CURRENT address of each type per customer.
CREATE UNIQUE INDEX ux_customer_address_current
    ON customer_address (customer_id, address_type) WHERE valid_to IS NULL;

-- Account: a customer's bank account. Opened as PENDING until the fraud
-- decision makes it ACTIVE or REJECTED.
CREATE TABLE account (
    account_id            bigint      GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    branch_id             integer     NOT NULL REFERENCES branch (branch_id),
    account_number        varchar(9)  NOT NULL CHECK (account_number ~ '^[0-9]{6,9}$'),
    product_code          varchar(20) NOT NULL REFERENCES product (product_code),
    account_status        varchar(8)  NOT NULL DEFAULT 'PENDING'
                          CHECK (account_status IN ('PENDING','ACTIVE','REJECTED','CLOSED')),
    channel               varchar(6)  NOT NULL CHECK (channel IN ('MOBILE','BRANCH','WEB')),
    opened_at             timestamptz NOT NULL DEFAULT now(),
    activated_at          timestamptz CHECK (activated_at >= opened_at),
    closed_at             timestamptz CHECK (closed_at >= opened_at),
    onboarding_session_id uuid,                                      -- logical key -> identity_fraud.onboarding_session
    version               integer     NOT NULL DEFAULT 1 CHECK (version >= 1),  -- aggregate version
    UNIQUE (branch_id, account_number)                               -- account number is unique within a branch (BSB)
);

-- Account holder: which customers own which accounts (many-to-many).
CREATE TABLE account_holder (
    account_id  bigint      NOT NULL REFERENCES account (account_id),
    customer_id bigint      NOT NULL REFERENCES customer (customer_id),
    holder_role varchar(7)  NOT NULL CHECK (holder_role IN ('PRIMARY','JOINT')),
    added_at    timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (account_id, customer_id)
);
-- Exactly one PRIMARY holder per account (JOINT holders are unlimited).
CREATE UNIQUE INDEX ux_account_holder_primary
    ON account_holder (account_id) WHERE holder_role = 'PRIMARY';
CREATE INDEX ix_account_holder_customer ON account_holder (customer_id);

-- Outbox: business events written in the SAME transaction as the change,
-- then read by Debezium and published to Kafka (transactional outbox pattern).
-- Column names follow Debezium's outbox event router defaults.
CREATE TABLE outbox (
    id            uuid         PRIMARY KEY DEFAULT gen_random_uuid(),  -- event id
    aggregatetype varchar(255) NOT NULL CHECK (aggregatetype IN ('account','customer')),  -- picks the Kafka topic
    aggregateid   varchar(255) NOT NULL,                              -- account_id or customer_id = Kafka key
    type          varchar(255) NOT NULL CHECK (type IN ('CustomerCreated','CustomerDetailsUpdated',
                                                        'AccountOpened','AccountActivated',
                                                        'AccountRejected','AccountSnapshot')),
    event_version integer      NOT NULL,                              -- aggregate version after the change
    payload       jsonb        NOT NULL,                              -- full event, see docs/event-contract.md
    tx_id         bigint       NOT NULL DEFAULT txid_current(),       -- source transaction id, for lineage
    created_at    timestamptz  NOT NULL DEFAULT now()
);
CREATE INDEX ix_outbox_created_at ON outbox (created_at);


-- #############################################################################
-- 2. identity_fraud – identity verification and fraud platform (ER section 2)
-- #############################################################################
\connect identity_fraud

-- Device: a phone/computer seen during onboarding, identified by a hashed fingerprint.
CREATE TABLE device (
    device_id          bigint      GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    device_fingerprint varchar(64) NOT NULL UNIQUE,                  -- hash, never the raw device id
    os                 varchar(50),
    first_seen_at      timestamptz NOT NULL DEFAULT now()
);

-- Onboarding session: one sign-up journey on one device.
CREATE TABLE onboarding_session (
    session_id   uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
    customer_id  bigint,                                             -- logical key -> core_banking.customer (NULL until known)
    device_id    bigint      NOT NULL REFERENCES device (device_id),
    ip_address   inet,
    channel      varchar(6)  NOT NULL CHECK (channel IN ('MOBILE','BRANCH','WEB')),
    started_at   timestamptz NOT NULL DEFAULT now(),
    completed_at timestamptz CHECK (completed_at >= started_at)
);
CREATE INDEX ix_onboarding_session_customer ON onboarding_session (customer_id);
CREATE INDEX ix_onboarding_session_device   ON onboarding_session (device_id);  -- "customers sharing a device"

-- KYC verification: identity document check. Stores only a HASH of the
-- document number (64 hex chars, e.g. SHA-256), never the number itself.
CREATE TABLE kyc_verification (
    kyc_id              bigint      GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    session_id          uuid        NOT NULL REFERENCES onboarding_session (session_id),
    customer_id         bigint      NOT NULL,                        -- logical key -> core_banking.customer
    document_type       varchar(15) NOT NULL CHECK (document_type IN ('PASSPORT','DRIVER_LICENCE','MEDICARE')),
    document_token      char(64)    NOT NULL CHECK (document_token ~ '^[0-9a-f]{64}$'),
    verification_source varchar(13) NOT NULL CHECK (verification_source IN ('DVS','CREDIT_BUREAU')),
    result              varchar(5)  NOT NULL CHECK (result IN ('PASS','FAIL','REFER')),
    verified_at         timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX ix_kyc_verification_customer ON kyc_verification (customer_id);

-- Watchlist screening: sanctions and politically exposed person (PEP) checks.
CREATE TABLE watchlist_screening (
    screening_id bigint      GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    customer_id  bigint      NOT NULL,                               -- logical key -> core_banking.customer
    list_type    varchar(9)  NOT NULL CHECK (list_type IN ('SANCTIONS','PEP')),
    match_status varchar(9)  NOT NULL CHECK (match_status IN ('CLEAR','POSSIBLE','CONFIRMED')),
    screened_at  timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX ix_watchlist_screening_customer ON watchlist_screening (customer_id);

-- Risk assessment: the fraud engine's score and decision for a new account.
CREATE TABLE risk_assessment (
    assessment_id   bigint       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    account_id      bigint       NOT NULL,                           -- logical key -> core_banking.account
    customer_id     bigint       NOT NULL,                           -- logical key -> core_banking.customer
    session_id      uuid         REFERENCES onboarding_session (session_id),
    source_event_id uuid         UNIQUE,                             -- the AccountOpened event scored (one assessment per event)
    risk_score      numeric(5,2) NOT NULL CHECK (risk_score BETWEEN 0 AND 100),
    decision        varchar(7)   NOT NULL CHECK (decision IN ('APPROVE','REVIEW','DECLINE')),
    reason_codes    text,                                            -- e.g. 'SHARED_DEVICE,KYC_REFER'
    model_version   varchar(20)  NOT NULL,                           -- e.g. 'rules-v1'
    assessed_at     timestamptz  NOT NULL DEFAULT now()
);
CREATE INDEX ix_risk_assessment_account ON risk_assessment (account_id);

-- Processed event: ids of Kafka events already handled (makes the consumer idempotent).
CREATE TABLE processed_event (
    event_id     uuid        PRIMARY KEY,
    processed_at timestamptz NOT NULL DEFAULT now()
);


-- #############################################################################
-- 3. crm – customer relationship management (ER section 3)
-- #############################################################################
\connect crm

-- CRM contact: CRM's copy of a customer, kept in sync from core_banking events.
CREATE TABLE crm_contact (
    contact_id        bigint       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    customer_id       bigint       NOT NULL UNIQUE,                  -- golden key from core_banking
    full_name         varchar(201) NOT NULL,
    email             varchar(255),
    mobile            varchar(16),
    marketing_consent boolean      NOT NULL DEFAULT false,
    source_version    integer      NOT NULL,                         -- core customer.version last applied
    synced_at         timestamptz  NOT NULL DEFAULT now()
);

-- CRM financial account: CRM's copy of an account.
CREATE TABLE crm_financial_account (
    fin_account_id bigint      GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    account_id     bigint      NOT NULL UNIQUE,                      -- golden key from core_banking
    contact_id     bigint      NOT NULL REFERENCES crm_contact (contact_id),
    product_code   varchar(20) NOT NULL,
    account_status varchar(8)  NOT NULL CHECK (account_status IN ('PENDING','ACTIVE','REJECTED','CLOSED')),
    opened_at      timestamptz NOT NULL,
    source_version integer     NOT NULL,                             -- core account.version last applied
    synced_at      timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX ix_crm_financial_account_contact ON crm_financial_account (contact_id);

-- CRM case: service cases owned by CRM itself (not synced from core_banking).
CREATE TABLE crm_case (
    case_id     bigint       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    contact_id  bigint       NOT NULL REFERENCES crm_contact (contact_id),
    case_type   varchar(15)  NOT NULL CHECK (case_type IN ('ONBOARDING_HELP','COMPLAINT','ENQUIRY')),
    case_status varchar(11)  NOT NULL DEFAULT 'OPEN' CHECK (case_status IN ('OPEN','IN_PROGRESS','CLOSED')),
    owner_user  varchar(100),                                        -- CRM staff member handling the case
    opened_at   timestamptz  NOT NULL DEFAULT now(),
    closed_at   timestamptz  CHECK (closed_at >= opened_at)
);
CREATE INDEX ix_crm_case_contact ON crm_case (contact_id);

-- Processed event: ids of Kafka events already handled (idempotent consumer).
CREATE TABLE processed_event (
    event_id     uuid        PRIMARY KEY,
    processed_at timestamptz NOT NULL DEFAULT now()
);


-- #############################################################################
-- 4. loyalty – rewards and loyalty platform (ER section 4)
-- #############################################################################
\connect loyalty

-- Loyalty member: one per customer. Enrolled only with an ACTIVE account and
-- marketing consent (rule applied by the loyalty consumer).
CREATE TABLE loyalty_member (
    member_id         bigint      GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    customer_id       bigint      NOT NULL UNIQUE,                   -- golden key from core_banking
    marketing_consent boolean     NOT NULL DEFAULT false,
    member_status     varchar(10) NOT NULL DEFAULT 'INELIGIBLE'
                      CHECK (member_status IN ('ENROLLED','INELIGIBLE','UNENROLLED')),
    joined_at         timestamptz,                                   -- set when first ENROLLED
    source_version    integer     NOT NULL,                          -- core customer.version last applied
    synced_at         timestamptz NOT NULL DEFAULT now()
);

-- Loyalty account link: which accounts earn points for which member.
CREATE TABLE loyalty_account_link (
    account_id     bigint      PRIMARY KEY,                          -- golden key from core_banking
    member_id      bigint      NOT NULL REFERENCES loyalty_member (member_id),
    product_code   varchar(20) NOT NULL,
    account_status varchar(8)  NOT NULL CHECK (account_status IN ('PENDING','ACTIVE','REJECTED','CLOSED')),
    eligible       boolean     NOT NULL DEFAULT false,               -- true only if ACTIVE and consent
    source_version integer     NOT NULL,                             -- core account.version last applied
    synced_at      timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX ix_loyalty_account_link_member ON loyalty_account_link (member_id);

-- Loyalty offer: bonus-point offers, optionally tied to one product.
CREATE TABLE loyalty_offer (
    offer_id              integer      GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    offer_name            varchar(100) NOT NULL,
    eligible_product_code varchar(20),                               -- logical key -> core_banking.product (NULL = any product)
    bonus_points          integer      NOT NULL CHECK (bonus_points > 0),
    valid_from            date         NOT NULL,
    valid_to              date         CHECK (valid_to >= valid_from)
);

-- Member offer: offers assigned to members (many-to-many).
CREATE TABLE member_offer (
    member_id         bigint      NOT NULL REFERENCES loyalty_member (member_id),
    offer_id          integer     NOT NULL REFERENCES loyalty_offer (offer_id),
    assigned_at       timestamptz NOT NULL DEFAULT now(),
    redemption_status varchar(8)  NOT NULL DEFAULT 'ASSIGNED' CHECK (redemption_status IN ('ASSIGNED','REDEEMED','EXPIRED')),
    PRIMARY KEY (member_id, offer_id)
);

-- Processed event: ids of Kafka events already handled (idempotent consumer).
CREATE TABLE processed_event (
    event_id     uuid        PRIMARY KEY,
    processed_at timestamptz NOT NULL DEFAULT now()
);


-- #############################################################################
-- 5. westcity_dw – integrated data warehouse (ER sections 5, 6 and 7)
--    Layers are separate schemas:
--      staging   raw copies of Kafka events (tables added with the DW lander)
--      raw_vault Data Vault 2.0: hubs, links, insert-only satellites
--      mart      star schema for reporting
--      ops       audit (ETL runs, quarantine) and reconciliation
-- #############################################################################
\connect westcity_dw

CREATE SCHEMA staging;
CREATE SCHEMA raw_vault;
CREATE SCHEMA mart;
CREATE SCHEMA ops;

-- =============================================================================
-- 5a. ops – audit, data quality and reconciliation (ER section 7)
--     Created first because the other layers record which ETL run loaded them.
-- =============================================================================

-- ETL run: one row per warehouse load; its run_id is stamped on every row loaded.
CREATE TABLE ops.etl_run (
    run_id         bigint       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    job_name       varchar(100) NOT NULL,
    script_version varchar(40)  NOT NULL,                            -- version of the ETL script, e.g. 'v1'
    started_at     timestamptz  NOT NULL DEFAULT now(),
    finished_at    timestamptz,
    status         varchar(9)   NOT NULL DEFAULT 'RUNNING' CHECK (status IN ('RUNNING','SUCCEEDED','FAILED')),
    rows_read      integer      NOT NULL DEFAULT 0,
    rows_loaded    integer      NOT NULL DEFAULT 0,
    rows_rejected  integer      NOT NULL DEFAULT 0
);

-- DQ quarantine: rows rejected by a data-quality rule, kept with the reason.
CREATE TABLE ops.dq_quarantine (
    quarantine_id  bigint       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    run_id         bigint       NOT NULL REFERENCES ops.etl_run (run_id),
    source_table   varchar(100) NOT NULL,
    record_key     varchar(100),
    rule_name      varchar(100) NOT NULL,
    reason         text         NOT NULL,
    raw_record     jsonb,                                            -- the rejected row as it arrived
    quarantined_at timestamptz  NOT NULL DEFAULT now()
);

-- Recon SLA: how long each target may lag before a difference counts as OPEN.
CREATE TABLE ops.recon_sla (
    target_system varchar(7) PRIMARY KEY CHECK (target_system IN ('CRM','LOYALTY','FRAUD','DW')),
    sla_minutes   integer    NOT NULL CHECK (sla_minutes > 0)
);

-- Recon run: one execution of the reconciliation (core_banking vs targets).
CREATE TABLE ops.recon_run (
    recon_run_id     bigint      GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    started_at       timestamptz NOT NULL DEFAULT now(),
    finished_at      timestamptz,
    accounts_checked integer     NOT NULL DEFAULT 0,
    breaks_found     integer     NOT NULL DEFAULT 0
);

-- Recon break: one difference found for one account in one target system.
CREATE TABLE ops.recon_break (
    break_id            bigint      GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    recon_run_id        bigint      NOT NULL REFERENCES ops.recon_run (recon_run_id),
    target_system       varchar(7)  NOT NULL REFERENCES ops.recon_sla (target_system),
    account_id          bigint      NOT NULL,                        -- logical key -> core_banking.account
    break_type          varchar(8)  NOT NULL CHECK (break_type IN ('MISSING','STALE','MISMATCH')),
    severity            varchar(8)  NOT NULL CHECK (severity IN ('CRITICAL','HIGH','LOW')),
    first_detected_at   timestamptz NOT NULL DEFAULT now(),
    status              varchar(13) NOT NULL DEFAULT 'IN_FLIGHT'
                        CHECK (status IN ('IN_FLIGHT','OPEN','AUTO_REPAIRED','RESOLVED')),
    repair_requested_at timestamptz,                                 -- set by a manual repair (e.g. snapshot)
    resolved_at         timestamptz,
    note                text
);
CREATE INDEX ix_recon_break_account ON ops.recon_break (account_id, target_system);

-- Consumer health: latest Kafka position of each consumer, to show lag.
CREATE TABLE ops.consumer_health (
    consumer_name    varchar(9)   NOT NULL CHECK (consumer_name IN ('FRAUD','CRM','LOYALTY','DW_LANDER')),
    topic            varchar(255) NOT NULL,
    kafka_partition  integer      NOT NULL,
    committed_offset bigint,
    end_offset       bigint,
    lag              bigint,                                         -- end_offset - committed_offset
    updated_at       timestamptz  NOT NULL DEFAULT now(),
    PRIMARY KEY (consumer_name, topic, kafka_partition)
);

-- =============================================================================
-- 5b. raw_vault – Data Vault 2.0 (ER section 5)
--     Hash keys are the MD5 (32 hex chars) of the business key.
--     Hubs = business keys, links = relationships, satellites = history.
--     Satellites are INSERT-ONLY: a change adds a row with a new load_dts.
--     run_id is a logical reference to ops.etl_run (as in the ER design).
-- =============================================================================

-- Hubs: one row per business key, ever.
CREATE TABLE raw_vault.hub_customer (
    hk_customer   char(32)     PRIMARY KEY,                          -- MD5 of customer_id
    customer_id   bigint       NOT NULL UNIQUE,                      -- business key
    load_dts      timestamptz  NOT NULL,
    record_source varchar(100) NOT NULL
);

CREATE TABLE raw_vault.hub_account (
    hk_account    char(32)     PRIMARY KEY,                          -- MD5 of account_id
    account_id    bigint       NOT NULL UNIQUE,
    load_dts      timestamptz  NOT NULL,
    record_source varchar(100) NOT NULL
);

CREATE TABLE raw_vault.hub_product (
    hk_product    char(32)     PRIMARY KEY,                          -- MD5 of product_code
    product_code  varchar(20)  NOT NULL UNIQUE,
    load_dts      timestamptz  NOT NULL,
    record_source varchar(100) NOT NULL
);

CREATE TABLE raw_vault.hub_device (
    hk_device          char(32)     PRIMARY KEY,                     -- MD5 of device_fingerprint
    device_fingerprint varchar(64)  NOT NULL UNIQUE,
    load_dts           timestamptz  NOT NULL,
    record_source      varchar(100) NOT NULL
);

-- Links: one row per relationship between business keys.
CREATE TABLE raw_vault.link_account_holder (
    hk_account_holder char(32)     PRIMARY KEY,                      -- MD5 of account_id + customer_id
    hk_account        char(32)     NOT NULL REFERENCES raw_vault.hub_account (hk_account),
    hk_customer       char(32)     NOT NULL REFERENCES raw_vault.hub_customer (hk_customer),
    holder_role       varchar(7)   NOT NULL CHECK (holder_role IN ('PRIMARY','JOINT')),
    load_dts          timestamptz  NOT NULL,
    record_source     varchar(100) NOT NULL,
    UNIQUE (hk_account, hk_customer)
);

CREATE TABLE raw_vault.link_account_product (
    hk_account_product char(32)     PRIMARY KEY,                     -- MD5 of account_id + product_code
    hk_account         char(32)     NOT NULL REFERENCES raw_vault.hub_account (hk_account),
    hk_product         char(32)     NOT NULL REFERENCES raw_vault.hub_product (hk_product),
    load_dts           timestamptz  NOT NULL,
    record_source      varchar(100) NOT NULL,
    UNIQUE (hk_account, hk_product)
);

CREATE TABLE raw_vault.link_customer_device (
    hk_customer_device char(32)     PRIMARY KEY,                     -- MD5 of customer_id + device_fingerprint
    hk_customer        char(32)     NOT NULL REFERENCES raw_vault.hub_customer (hk_customer),
    hk_device          char(32)     NOT NULL REFERENCES raw_vault.hub_device (hk_device),
    load_dts           timestamptz  NOT NULL,
    record_source      varchar(100) NOT NULL,
    UNIQUE (hk_customer, hk_device)
);

-- Satellites: descriptive attributes with full history.
-- hash_diff = MD5 of all attribute values; a new row is inserted only when it changes.
CREATE TABLE raw_vault.sat_customer_details (
    hk_customer       char(32)     NOT NULL REFERENCES raw_vault.hub_customer (hk_customer),
    load_dts          timestamptz  NOT NULL,
    hash_diff         char(32)     NOT NULL,
    first_name        varchar(100),
    last_name         varchar(100),
    date_of_birth     date,
    email             varchar(255),
    mobile            varchar(16),
    residential_state varchar(3),
    marketing_consent boolean,
    src_commit_ts     timestamptz,                                   -- when the change committed in the source
    record_source     varchar(100) NOT NULL,
    run_id            bigint       NOT NULL,                         -- logical ref -> ops.etl_run
    PRIMARY KEY (hk_customer, load_dts)
);

CREATE TABLE raw_vault.sat_customer_kyc (
    hk_customer      char(32)     NOT NULL REFERENCES raw_vault.hub_customer (hk_customer),
    load_dts         timestamptz  NOT NULL,
    hash_diff        char(32)     NOT NULL,
    kyc_result       varchar(5),
    document_type    varchar(15),
    watchlist_status varchar(9),
    verified_at      timestamptz,
    record_source    varchar(100) NOT NULL,
    run_id           bigint       NOT NULL,
    PRIMARY KEY (hk_customer, load_dts)
);

CREATE TABLE raw_vault.sat_account_state (
    hk_account     char(32)     NOT NULL REFERENCES raw_vault.hub_account (hk_account),
    load_dts       timestamptz  NOT NULL,
    hash_diff      char(32)     NOT NULL,
    account_status varchar(8),
    channel        varchar(6),
    bsb            char(6),
    account_number varchar(9),
    opened_at      timestamptz,
    activated_at   timestamptz,
    source_version integer,                                          -- core account.version
    src_commit_ts  timestamptz,
    record_source  varchar(100) NOT NULL,
    run_id         bigint       NOT NULL,
    PRIMARY KEY (hk_account, load_dts)
);

CREATE TABLE raw_vault.sat_account_risk (
    hk_account    char(32)     NOT NULL REFERENCES raw_vault.hub_account (hk_account),
    load_dts      timestamptz  NOT NULL,
    hash_diff     char(32)     NOT NULL,
    risk_score    numeric(5,2),
    decision      varchar(7),
    model_version varchar(20),
    assessed_at   timestamptz,
    record_source varchar(100) NOT NULL,
    run_id        bigint       NOT NULL,
    PRIMARY KEY (hk_account, load_dts)
);

-- =============================================================================
-- 5c. mart – star schema for reporting (ER section 6)
-- =============================================================================

-- Date dimension: one row per calendar day, key = YYYYMMDD (e.g. 20261005).
CREATE TABLE mart.dim_date (
    date_key        integer PRIMARY KEY CHECK (date_key BETWEEN 19000101 AND 29991231),
    calendar_date   date    NOT NULL UNIQUE,
    day_of_week     integer NOT NULL CHECK (day_of_week BETWEEN 1 AND 7),   -- ISO: 1 = Monday
    month           integer NOT NULL CHECK (month BETWEEN 1 AND 12),
    quarter         integer NOT NULL CHECK (quarter BETWEEN 1 AND 4),
    year            integer NOT NULL,
    is_business_day boolean NOT NULL
);

-- Customer dimension, SCD type 2: a change closes the current row
-- (valid_to, is_current = false) and adds a new one.
CREATE TABLE mart.dim_customer (
    customer_key      bigint      GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,  -- surrogate key
    customer_id       bigint      NOT NULL,                          -- business key
    age_band          varchar(10),                                   -- e.g. '25-34'
    residential_state varchar(3),
    marketing_consent boolean,
    valid_from        timestamptz NOT NULL,
    valid_to          timestamptz,                                   -- NULL = current version
    is_current        boolean     NOT NULL DEFAULT true
);
-- Only one current row per customer.
CREATE UNIQUE INDEX ux_dim_customer_current ON mart.dim_customer (customer_id) WHERE is_current;

CREATE TABLE mart.dim_product (
    product_key  integer      GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    product_code varchar(20)  NOT NULL UNIQUE,
    product_name varchar(100) NOT NULL,
    product_type varchar(20)  NOT NULL
);

CREATE TABLE mart.dim_channel (
    channel_key integer    GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    channel     varchar(6) NOT NULL UNIQUE
);

CREATE TABLE mart.dim_branch (
    branch_key  integer      GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    bsb         char(6)      NOT NULL UNIQUE,
    branch_name varchar(100) NOT NULL,
    state       varchar(3)   NOT NULL
);

-- Fact: one row per account opening (grain = account).
CREATE TABLE mart.fact_account_opening (
    account_id              bigint       PRIMARY KEY,                -- degenerate dimension
    open_date_key           integer      NOT NULL REFERENCES mart.dim_date (date_key),
    customer_key            bigint       NOT NULL REFERENCES mart.dim_customer (customer_key),  -- PRIMARY holder
    product_key             integer      NOT NULL REFERENCES mart.dim_product (product_key),
    channel_key             integer      NOT NULL REFERENCES mart.dim_channel (channel_key),
    branch_key              integer      NOT NULL REFERENCES mart.dim_branch (branch_key),
    account_status          varchar(8)   NOT NULL,
    kyc_result              varchar(5),
    risk_decision           varchar(7),
    risk_score              numeric(5,2),
    minutes_to_activation   numeric(10,2),                           -- NULL if never activated
    shared_device_customers integer,                                 -- other customers on the same device
    opening_count           integer      NOT NULL DEFAULT 1 CHECK (opening_count = 1)  -- for SUM() in reports
);

-- Fact: one row per event per target system, measuring propagation latency.
CREATE TABLE mart.fact_event_propagation (
    event_id         uuid          NOT NULL,
    target_system    varchar(7)    NOT NULL CHECK (target_system IN ('FRAUD','CRM','LOYALTY','DW')),
    account_id       bigint,
    date_key         integer       NOT NULL REFERENCES mart.dim_date (date_key),
    event_type       varchar(30)   NOT NULL,
    event_created_ts timestamptz   NOT NULL,                         -- when the event was written to the outbox
    applied_ts       timestamptz,                                    -- when the target applied it (NULL = not yet)
    latency_seconds  numeric(12,3),                                  -- applied_ts - event_created_ts
    within_sla       boolean,
    PRIMARY KEY (event_id, target_system)
);
